contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address account, uint256 id) public payable {
        bool zeroAccount = account == address(0);
        uint256 observed;
        bool reverted;
        uint256 bal = c.balanceOf(account, id); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            observed = bal;
            reverted = false;
        }
        assert(zeroAccount ? reverted : (!reverted && observed == 0));
    }

    receive() external payable {}
}

